const items = $input.all();
const now = new Date();
const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);

const validNews = [];
const seenURLs = new Set();
const seenTitles = new Set();

const BLACKLIST = [
  /гороскоп/i, /зодиак/i, /астролог/i, /ретроград/i,
  /нумеролог/i, /таро/i, /эзотерик/i, /магия/i,
  /предсказан/i, /гадал/i, /экстрасенс/i
];

const GEO_AMUR = [
  /благовещенск/i, /амурск(ая|ой|ую|ом|ий|ого|ими)/i, 
  /приамурь/i, /зея/i, /белогорск/i, /тында/i, /свободн(ый|ого|ом|ая)/i,
  /райчихинск/i, /шимановск/i, /сковородино/i
];

const CHINA_KEYWORDS = [
  /китай/i, /кнр/i, /хэйхэ/i, /харбин/i, /пекин/i,
  /китайск(ий|ая|ие|ого|ую|ими)/i, /поднебесн/i,
  /погранпереход/i, /безвиз/i,
  /китайско.{1,20}российск/i, /российско.{1,20}китайск/i
];

const BUSINESS_KEYWORDS = [
  /бизнес/i, /экономик/i, /торговл/i, /экспорт/i, /импорт/i,
  /инвестиц/i, /предприним/i, /компани/i, /производств/i,
  /рынок/i, /финанс/i, /банк/i, /строительств/i,
  /промышленн/i, /логистик/i, /таможн/i,
  /сельхоз/i, /агро/i, /туризм/i, /контракт/i
];

let stats = {
  total: items.length,
  old: 0,
  duplicateURL: 0,
  duplicateTitle: 0,
  blacklisted: 0,
  noGeoNoChina: 0,
  irrelevant: 0,
  invalid: 0,
  kept: 0
};

console.log(`Обработка ${items.length} элементов...`);

for (const item of items) {
  try {
    const data = item.json || {};

    if (!data.title || !data.link) {
      stats.invalid++;
      continue;
    }

    const title = String(data.title).trim();
    const link = String(data.link).trim();
    const description = String(
      data.description || 
      data.contentSnippet || 
      data.content || 
      data['content:encoded'] || 
      ''
    ).trim();
    const pubDate = data.pubDate || data.isoDate || data.published || '';
    const source = String(
      data.creator || 
      data.author || 
      data['dc:creator'] ||
      data.source?.title ||
      'Unknown'
    ).trim();

    if (pubDate) {
      const articleDate = new Date(pubDate);
      if (!isNaN(articleDate.getTime()) && articleDate < yesterday) {
        stats.old++;
        continue;
      }
    }

    const normalizedURL = link.toLowerCase().replace(/[?#].*$/, '');
    if (seenURLs.has(normalizedURL)) {
      stats.duplicateURL++;
      continue;
    }
    seenURLs.add(normalizedURL);

    const titleNormalized = title.toLowerCase().replace(/[^а-яёa-z0-9]/g, '').substring(0, 60);
    if (seenTitles.has(titleNormalized)) {
      stats.duplicateTitle++;
      continue;
    }
    seenTitles.add(titleNormalized);

    const cleanText = description
      .replace(/<[^>]*>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, '&')
      .replace(/&[a-z]+;/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .substring(0, 1500);

    const fullText = `${title} ${cleanText}`.toLowerCase();

    if (BLACKLIST.some(regex => regex.test(fullText))) {
      stats.blacklisted++;
      continue;
    }

    const hasGeo = GEO_AMUR.some(regex => regex.test(fullText));
    const hasChina = CHINA_KEYWORDS.some(regex => regex.test(fullText));
    const hasBusiness = BUSINESS_KEYWORDS.some(regex => regex.test(fullText));

    if (!hasGeo && !hasChina) {
      stats.noGeoNoChina++;
      continue;
    }

    if ((hasGeo || hasChina) && !hasBusiness) {
      const IMPORTANT = [
        /губернатор/i, /правительств/i, /администрац/i, /мэр/i,
        /бюджет/i, /субсиди/i, /инфраструктур/i, /мост/i
      ];

      if (!IMPORTANT.some(regex => regex.test(fullText))) {
        stats.irrelevant++;
        continue;
      }
    }

    let relevanceScore = 0;
    if (hasGeo) relevanceScore += 5;
    if (hasChina) relevanceScore += 3;
    if (hasBusiness) relevanceScore += 2;
    if (hasGeo && hasChina && hasBusiness) relevanceScore += 1;

    validNews.push({
      title,
      link,
      description: cleanText,
      pubDate: pubDate || new Date().toISOString(),
      source,
      relevanceScore
    });

    stats.kept++;

  } catch (error) {
    console.error(`Ошибка: ${error.message}`);
    stats.invalid++;
  }
}

validNews.sort((a, b) => {
  if (b.relevanceScore !== a.relevanceScore) {
    return b.relevanceScore - a.relevanceScore;
  }
  return new Date(b.pubDate) - new Date(a.pubDate);
});

console.log('Статистика фильтрации:', stats);

if (validNews.length === 0) {
  console.warn('Релевантных новостей не найдено');
  return [{ json: { error: 'No relevant news', stats } }];
}

console.log(`✅ Отобрано ${validNews.length} релевантных новостей`);
return validNews.slice(0, 20).map(news => ({ json: news }));
